env.RESTERM_PICKER_CODE:
import json
import sys
from pathlib import Path

env_file, state_file = map(Path, sys.argv[1:3])
if not env_file.is_file():
    sys.exit('Resterm: no environment file found')
try:
    data = json.loads(env_file.read_text(encoding='utf-8'))
except (OSError, ValueError) as exc:
    sys.exit(f'Resterm: cannot read environment file: {exc}')
if not isinstance(data, dict) or '$groups' in data:
    sys.exit('Resterm: expected a file with named environments (grouped environments are not supported by this picker)')
names = [name for name, value in data.items() if isinstance(value, dict) and not name.startswith('$') and '\n' not in name]
if not names:
    sys.exit('Resterm: no named environments found')
selected = state_file.read_text(encoding='utf-8').strip() if state_file.is_file() else ''
print(f'Environment file: {env_file}')
print(' 0. Automatic' + (' *' if not selected else ''))
for index, name in enumerate(names, 1):
    print(f' {index}. {name}' + (' *' if name == selected else ''))
try:
    choice = input('Select environment (Enter to cancel): ').strip()
except EOFError:
    sys.exit(0)
if not choice:
    sys.exit(0)
if not choice.isdecimal() or int(choice) > len(names):
    sys.exit('Resterm: invalid selection')
if choice == '0':
    state_file.unlink(missing_ok=True)
    print('Resterm environment: automatic')
else:
    name = names[int(choice) - 1]
    state_file.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    state_file.write_text(name + '\n', encoding='utf-8')
    print(f'Resterm environment: {name}')
